head.script:
// https://inswave01.atlassian.net/browse/WAEA-1166



// 테스트 설명, 유효성 값 설정
//  ★ _1 : @description 부가 문구 + options 파라미터 공통 + Excel 파일 선택 팝업창 옵션(popupUrl, wframe). description 은 분리 샘플 공통.
scwin.tData = {
    "description" : "[gridView > M > advancedExcelUpload]<br/>Excel 파일을 업로드하여 GridView 의 데이터로 설정합니다.",
    "validation" : [
        "JDK 1.5 이상에서 사용할 수 있으며 GridView 에 DataList 가 바인딩 되어 있어야 합니다.",
        "Excel 97 이상의 엑셀 파일을 지원하며 Excel 5.0/7.0 은 지원하지 않습니다.",
        "options(필수) 파라미터로 Excel 데이터 업로드 옵션을 객체로 설정합니다.",
        "업로드 옵션을 기본값으로만 설정할 경우 빈 객체({})로 설정해야 합니다.",
        "popupUrl(선택) 파라미터로 Excel 파일 선택 팝업창의 경로(URL)를 설정합니다.",
        "기본 제공하는 Excel 파일 선택 팝업창 대신 커스텀 화면으로 바꾸는 경우에 설정하며 규약에 맞게 구현하여야 합니다.",
        "popupUrl(선택) 파라미터값을 설정하지 않으면 엔진 기본 팝업창 경로(uiplugin/grid/upload/advancedfileUpload.html)가 적용됩니다.",
        "wframe(선택) 파라미터로 Excel 파일 선택 팝업창을 WFrame 으로 생성할지 여부를 설정합니다.",
        "wframe(선택) 파라미터를 true 로 설정 시 WFrame 으로 Excel 파일 선택 팝업창을 생성합니다.",
        "wframe(선택) 파라미터를 false 로 설정 시 별도의 팝업으로 Excel 파일 선택 팝업창을 생성합니다.",
        "wframe(선택) 파라미터를 생략하면 기본값 false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : DataList 가 바인딩된 4 Column GridView 를 동적 생성한다.
//  · advancedExcelUpload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- name1~name4 4개 Column 그리드에 초기 데이터 4행(col1_1 ~ col4_4)이 바인딩되어 있음\n- 테스트용 Excel : TSQA/src/sample/gridView/data/upload/ts_gridView_M_advancedExcelUpload_1/ts_gridView_M_advancedExcelUpload_1_upload.xlsx (Excel 2007 이상 형식, 0행 name1~name4 / 1~3행 xlsA1~xlsC4 / 4행 footer1~footer4)\n- 커스텀 팝업 화면(.html : /sample/common_link/gridView_M_advancedExcelUpload_popup_1.html , .xml : /sample/common_link/gridView_M_advancedExcelUpload_popup_1.xml)은 popupUrl 반영 여부 확인용이며 파일 선택 기능은 구현하지 않음\n- popupUrl 항목을 선택해도 wframe 값은 바뀌지 않으므로 popupUrl 과 wframe 을 각각 선택해야 함\n- popupUrl 값의 형태에 맞는 wframe 값은 .html 파일 경로는 wframe false(별도 팝업창), .xml 화면 경로는 wframe true(WFrame 레이어)임\n- 값 형태가 맞지 않는 조합은 .html 파일 경로 + wframe true 이면 빈 레이어가 열리고, .xml 화면 경로 + wframe false 이면 팝업창에 not exist 오류 화면이 표시됨\n[절차]\n1. par 옵션(popupUrl / wframe) 값을 선택한다\n2. advancedExcelUpload 버튼을 클릭한다\n3. (popupUrl 미설정인 경우) 열린 업로드 창에서 Excel 파일을 선택하고 File Upload 를 실행한다\n4. 업로드결과확인 버튼을 클릭한다\n[확인]\n- 2번 직후 결과창에 열린 팝업창의 종류(별도 팝업창 / 화면 내 WFrame 레이어)와 실제 열린 경로가 출력됨\n- 4번 출력에서 GridView 와 바인딩 DataList 에 반영된 Row 수와 데이터를 확인\n- 케이스를 바꿀 때는 업로드가 바인딩 DataList 를 교체하므로 Target 재생성 버튼으로 초기 데이터를 되돌린다"', '', 'label1');

    // DataList 생성 (col1~col4 / 4행)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (DataList 바인딩)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id
    });
    await $c.gcm.createBasicGridView(cList);
}



// par 옵션값으로 advancedExcelUpload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · 모든 파라미터가 미설정이면 빈 객체({}) 가 전달된다.
//  · wframe 은 Boolean 타입이므로 gdl_boolean 라벨(getText)을 Boolean 으로 변환하여 전달한다.
scwin.buildOptions = function () {
    let options = {};

    let vPopupUrl = par_popupUrl.getValue();
    if (vPopupUrl !== "") options.popupUrl = vPopupUrl;

    let vWframe = par_wframe.getText();
    if (vWframe === "true") {
        options.wframe = true;
    } else if (vWframe === "false") {
        options.wframe = false;
    }

    return options;
}



// advancedExcelUpload 실행
//  · 설정한 옵션값을 그대로 되출력하지 않고, 실제로 열린 Excel 파일 선택 팝업창의 형태와 경로를 읽어 출력한다.
//  · 별도 팝업창은 엔진이 호출 시점에 window 이름 fileupWindow 로 생성하므로, 그 자리에서 창 핸들을 한 번만 확보해 둔다.
//    (나중에 window.open 으로 창을 다시 찾으면 이미 닫힌 경우 빈 창(about:blank)이 새로 열리므로 확보해 둔 핸들로만 판정한다.)
scwin.btn_advancedExcelUpload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let options = scwin.buildOptions();
    scwin.gVar = { "wframe" : (options.wframe === true), "win" : null };

    let fnOpen = window.open;
    window.open = function (sUrl, sName) {
        let objWin = fnOpen.apply(window, arguments);
        if (sName === "fileupWindow") scwin.gVar.win = objWin;
        return objWin;
    };
    try {
        target1.advancedExcelUpload(options);
    } finally {
        window.open = fnOpen;
    }

    setTimeout(scwin.printUploadState, 1500);
}



// 실제로 열린 Excel 파일 선택 팝업창의 형태와 경로를 반환한다.
//  · wframe 적용 시 화면 내 레이어(WFrame ID 는 target ID + _excelPop_wframe), 미적용 시 window 이름 fileupWindow 인 별도 팝업창이다.
//  · 별도 팝업창은 로딩이 끝나기 전까지 about:blank 이므로 로딩 중임을 알린다.
//  · 팝업창이 이미 닫힌 경우 빈 창이 새로 열리지 않도록, 확보해 둔 창 핸들과 closed 값으로만 존재 여부를 판정한다.
scwin.getUploadInfo = function () {
    if (scwin.gVar === undefined) return null;

    if (scwin.gVar.wframe === true) {
        let objFrame = document.querySelector("[id$='_excelPop_wframe']");
        if (objFrame === null) return null;

        let objComp = WebSquare.util.getComponentById(objFrame.id);
        return { "kind" : "화면 내 WFrame 레이어", "url" : (objComp === null ? "" : objComp.getSrc()) };
    }

    let objWin = scwin.gVar.win;
    if (objWin === null || objWin.closed) return null;
    if (objWin.location.href === "about:blank") return { "loading" : true, "win" : objWin };

    return { "kind" : "별도 팝업창", "url" : objWin.location.href };
}



// 실제로 열린 Excel 파일 선택 팝업창의 형태(wframe)와 경로(popupUrl)를 출력한다.
//  · 팝업창 생성이 늦어질 수 있으므로 팝업창을 찾지 못하면 일정 횟수까지 다시 확인한다.
scwin.printUploadState = function (nRetry) {
    let bottom = wf_body_bottom.getObj("scwin");
    nRetry = nRetry || 0;

    let objInfo = scwin.getUploadInfo();

    if (objInfo !== null && objInfo.loading === true) {
        if (nRetry < 6) {
            setTimeout(function () { scwin.printUploadState(nRetry + 1); }, 500);
            return;
        }
        objInfo.win.close();
        objInfo = null;
    }

    if (objInfo === null) {
        if (nRetry < 6) {
            setTimeout(function () { scwin.printUploadState(nRetry + 1); }, 500);
            return;
        }
        bottom.setReturnValue("Excel 파일 선택 팝업창이 열려있지 않습니다.");
        return;
    }

    bottom.setReturnValue("팝업창 종류 : " + objInfo.kind + " / 실제 열린 경로 : " + objInfo.url);
}



// 업로드 결과 확인 : GridView 에 실제 반영된 데이터와 바인딩된 DataList 의 데이터를 함께 출력한다.
scwin.btn_getResult_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====btn_getResult_onclick=====");

    let cnt = target1.getRowCount();
    bottom.setReturnValue("GridView Row 수 : " + cnt + " / 바인딩 DataList Row 수 : " + dlt_bind.getRowCount());
    for (let i = 0; i < cnt; i++) {
        bottom.setReturnValue("[" + i + "] " + target1.getCellData(i, "col1") + " | " + target1.getCellData(i, "col2") + " | " + target1.getCellData(i, "col3") + " | " + target1.getCellData(i, "col4"));
    }
}
